/*
[演算法邏輯說明]
這是一個網路流 (Network Flow) 的問題。
給定 R 個累加列和 (cumulative row sums) 以及 C 個累加欄和 (cumulative column sums)，
我們首先計算每一列的實際和 RS[i] = CRS[i] - CRS[i-1] 以及每一欄的實際和 CS[j] = CCS[j] - CCS[j-1]。
題目限制矩陣中每個元素 A[i][j] 必須在 1 到 20 之間。
我們可以令 B[i][j] = A[i][j] - 1，則 0 <= B[i][j] <= 19。
調整後的列和為 RS'[i] = RS[i] - C，欄和為 CS'[j] = CS[j] - R。
建立一個二分圖：
1. 從源點 S 連接到每一列的節點 Row[i]，容量為 RS'[i]。
2. 從每一欄的節點 Col[j] 連接到匯點 T，容量為 CS'[j]。
3. 從每個 Row[i] 連接到每個 Col[j]，容量為 19。
使用最大流演算法（如 Dinic 或 Edmonds-Karp）求出流。
矩陣元素 A[i][j] 即為 Row[i] 到 Col[j] 的流量加 1。
*/

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>

using namespace std;

const int INF = 1e9;

struct Edge {
    int to, cap, flow, rev;
};

vector<Edge> adj[100];
int level[100];
int ptr[100];

void add_edge(int from, int to, int cap) {
    adj[from].push_back({to, cap, 0, (int)adj[to].size()});
    adj[to].push_back({from, 0, 0, (int)adj[from].size() - 1});
}

bool bfs(int s, int t) {
    memset(level, -1, sizeof(level));
    level[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (auto& edge : adj[v]) {
            if (edge.cap - edge.flow > 0 && level[edge.to] == -1) {
                level[edge.to] = level[v] + 1;
                q.push(edge.to);
            }
        }
    }
    return level[t] != -1;
}

int dfs(int v, int t, int pushed) {
    if (pushed == 0) return 0;
    if (v == t) return pushed;
    for (int& cid = ptr[v]; cid < (int)adj[v].size(); ++cid) {
        auto& edge = adj[v][cid];
        int tr = edge.to;
        if (level[v] + 1 != level[tr] || edge.cap - edge.flow == 0) continue;
        int push = dfs(tr, t, min(pushed, edge.cap - edge.flow));
        if (push == 0) continue;
        edge.flow += push;
        adj[tr][edge.rev].flow -= push;
        return push;
    }
    return 0;
}

int dinic(int s, int t) {
    int flow = 0;
    while (bfs(s, t)) {
        memset(ptr, 0, sizeof(ptr));
        while (int pushed = dfs(s, t, INF)) {
            flow += pushed;
        }
    }
    return flow;
}

int main() {
    int T_cases;
    if (!(cin >> T_cases)) return 0;
    for (int t_idx = 1; t_idx <= T_cases; ++t_idx) {
        int R, C;
        cin >> R >> C;
        vector<int> crs(R), ccs(C);
        for (int i = 0; i < R; ++i) cin >> crs[i];
        for (int j = 0; j < C; ++j) cin >> ccs[j];

        vector<int> rs(R), cs(C);
        rs[0] = crs[0];
        for (int i = 1; i < R; ++i) rs[i] = crs[i] - crs[i-1];
        cs[0] = ccs[0];
        for (int j = 1; j < C; ++j) cs[j] = ccs[j] - ccs[j-1];

        int s = 0, t = R + C + 1;
        for (int i = 0; i <= t; ++i) adj[i].clear();

        for (int i = 0; i < R; ++i) add_edge(s, i + 1, rs[i] - C);
        for (int j = 0; j < C; ++j) add_edge(R + j + 1, t, cs[j] - R);
        for (int i = 0; i < R; ++i) {
            for (int j = 0; j < C; ++j) {
                add_edge(i + 1, R + j + 1, 19);
            }
        }

        dinic(s, t);

        if (t_idx > 1) cout << endl;
        cout << "Matrix " << t_idx << endl;
        for (int i = 0; i < R; ++i) {
            for (int j = 0; j < C; ++j) {
                int val = 1;
                for (auto& edge : adj[i + 1]) {
                    if (edge.to == R + j + 1) {
                        val += edge.flow;
                        break;
                    }
                }
                cout << val << (j == C - 1 ? "" : " ");
            }
            cout << endl;
        }
    }
    return 0;
}
